  /**
   * Submit Python code for asynchronous execution in TouchDesigner.
   * Returns immediately with a taskId that can be polled via getTaskStatus().
   */
  async executeAsync(code, fromOp) {
    const data = await this._request(`${this.baseUrl}/execute_async`, {
      method: "POST",
      body: JSON.stringify({ code, fromOp: fromOp ?? "/" })
    });
    if (data && data.taskId) {
      return { taskId: data.taskId };
    }
    if (typeof data === "object" && data !== null) {
      const d = data;
      if (d.taskId)
        return { taskId: d.taskId };
      if (d.task_id)
        return { taskId: d.task_id };
      if (d.data && d.data.taskId)
        return { taskId: d.data.taskId };
    }
    throw new Error(`executeAsync: unexpected response \u2014 ${JSON.stringify(data).substring(0, 500)}`);
  }
  /**
   * Poll the status of an async execution task.
   */
  async getTaskStatus(taskId) {
    const data = await this._request(`${this.baseUrl}/task_status?taskId=${encodeURIComponent(taskId)}`);
    if (typeof data === "object" && data !== null) {
      const d = data;
      return {
        status: d.status ?? "unknown",
        result: d.result
      };
    }
    return { status: "unknown", result: data };
  }
  /**
   * Poll a task until it completes or times out.
   * @returns The task result on completion.
   * @throws If the task fails or the timeout is exceeded.
   */
  async waitForTask(taskId, timeoutMs = 3e4, pollIntervalMs = 500) {
    const deadline = Date.now() + timeoutMs;
    let lastStatus = "unknown";
    while (Date.now() < deadline) {
      const status = await this.getTaskStatus(taskId);
      lastStatus = status.status;
      if (status.status === "done") {
        return status.result;
      }
      if (status.status === "error" || status.status === "failed" || status.status === "cancelled") {
        throw new Error(`Task ${taskId} ${status.status}: ${JSON.stringify(status.result)}`);
      }
      await new Promise((resolve) => setTimeout(resolve, pollIntervalMs));
    }
    throw new Error(`Task ${taskId} timed out after ${timeoutMs}ms (last status: ${lastStatus})`);
  }
