  async getScreenshots(paths, maxSize) {
    const pathsJson = JSON.stringify(paths);
    const code = "import json,tempfile,base64,os\ntry:\n    plist = " + pathsJson + "\n    results = []\n    for p in plist:\n        try:\n            t = op(p)\n            if t is None:\n                results.append({'path':p,'error':'Not found'})\n            else:\n                tf = tempfile.NamedTemporaryFile(suffix='.png',delete=False).name\n                try:\n                    t.save(tf)\n                    b64 = base64.b64encode(open(tf,'rb').read()).decode()\n                    results.append({'path':t.path,'name':t.name,'image':b64})\n                finally:\n                    try: os.unlink(tf)\n                    except: pass\n        except Exception as e:\n            results.append({'path':p,'error':str(e)})\n    print(json.dumps({'success':True,'results':results,'count':len(results)}))\nexcept Exception as e:\n    print(json.dumps({'success':False,'error':str(e)}))";
    return this.executeJson(code);
  }
  /**
   * Take screenshots of multiple operators.
   * Returns a properly typed array of ScreenshotResult.
   */
  async screenshotMulti(paths, maxSize) {
    const pathsJson = JSON.stringify(paths);
    const resizeCode = maxSize !== void 0 ? `
        try:
            from PIL import Image as PILImage
            import io
            img_data = open(tf, 'rb').read()
            pil_img = PILImage.open(io.BytesIO(img_data))
            w, h = pil_img.size
            if w > ${maxSize} or h > ${maxSize}:
                if w >= h:
                    new_w = ${maxSize}
                    new_h = int(h * ${maxSize} / w)
                else:
                    new_h = ${maxSize}
                    new_w = int(w * ${maxSize} / h)
                pil_img = pil_img.resize((new_w, new_h), PILImage.LANCZOS)
                buf = io.BytesIO()
                pil_img.save(buf, format='PNG')
                b64 = base64.b64encode(buf.getvalue()).decode()
            else:
                b64 = base64.b64encode(img_data).decode()
        except ImportError:
            b64 = base64.b64encode(img_data).decode()` : "";
    const code = `import json,tempfile,base64,os
try:
    plist = ${pathsJson}
    results = []
    for p in plist:
        try:
            t = op(p)
            if t is None:
                results.append({'success':False,'path':p,'error':'Not found'})
            else:
                tf = tempfile.NamedTemporaryFile(suffix='.png',delete=False).name
                try:
                    t.save(tf)
                    b64 = base64.b64encode(open(tf,'rb').read()).decode()${resizeCode}
                    results.append({'success':True,'path':t.path,'image':b64})
                finally:
                    try: os.unlink(tf)
                    except: pass
        except Exception as e:
            results.append({'success':False,'path':p,'error':str(e)})
    print(json.dumps({'success':True,'results':results,'count':len(results)}))
except Exception as e:
    print(json.dumps({'success':False,'error':str(e)}))`;
    const result = await this.executeJson(code);
    return result.results ?? [];
  }
  // ---------------------------------------------------------------------------
  // td_pulse_param
  // ---------------------------------------------------------------------------
  async pulseParam(path, name) {
    const sp = PythonBuilder.esc(path);
    const sn = PythonBuilder.esc(name);
    const code = `import json
try:
    t = op('${sp}')
    if t is None: print(json.dumps({'success':False,'error':'Not found'}))
    else:
        found = False
        for p in t.pars('*'):
            if p.name.lower() == '${sn}'.lower():
                p.pulse()
                found = True
                print(json.dumps({'success':True,'path':t.path,'par':p.name}))
                break
        if not found:
            for p in t.pars('*'):
                if '${sn}'.lower() in p.name.lower():
                    p.pulse()
                    found = True
                    print(json.dumps({'success':True,'path':t.path,'par':p.name,'matched':'fuzzy'}))
                    break
        if not found:
            print(json.dumps({'success':False,'error':f'Parameter \\"${sn}\\" not found', 'available':[p.name for p in t.pars('*')[:10]]}))
except Exception as e:
    print(json.dumps({'success':False,'error':str(e)}))`;
    return this.executeJson(code);
  }
